<?php/*******************************************************************************************	Libreria de funciones para el Sistema de Puntos de Venta de Caprino - Salidas de MErcancia	Creador por: John Escobar	Iniciado: Agosto 11/2005	Ultima Modificación: Agosto 11/2005*******************************************************************************************//*******************************************************************************************	venta: Realiza todos los movimiento necesarios cuando se hace una venta en el punto de venta.	Parametros:			$frm: array con los datos de venta	Retorna:				Void*******************************************************************************************/function venta( $frm ){	Global $Nombre_Usuario, $ID_Usuario, $Table, $Key, $MOD;		//Insertar los Items en la tabla de detalles		$Items = $frm['ITEM'];		//print_r( $frm );		for($i = 1; $i <= $Items; $i++)	{				$iddetalle = get_maxID("DetalleFactura WHERE IDFactura = '$frm[IDFactura]' ","IDDetalleFactura");		$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$ValorU = "ValorU".$i;		$PrecioU = "Precio".$i;		$DescuentoRef = "Descuento".$i;				$ValorU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$ValorU]);		$PrecioU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$PrecioU]).".00";		$DescuentoRef = $frm[$DescuentoRef];				if( $frm[$Cantidad] > 0 )		{					$str_insert_detalle  = "INSERT INTO DetalleFactura ( IDDetalleFactura,IDFactura,IDCodificacionEspecifica,Cantidad,ValorU,PrecioU,DescuentoRef,UsuarioTrCr,FechaTrCr ) ";			$str_insert_detalle .= "VALUES ( '$iddetalle','$frm[IDFactura]','$frm[$IDCodificacion]','$frm[$Cantidad]','$ValorU','$PrecioU','$DescuentoRef','$frm[UsuarioTrCr]','$frm[FechaTrCr]' )";			//echo $str_insert_detalle .= "<br>";						db_query( $str_insert_detalle );						//insertar el log			insertlog($ID_Usuario,"DetalleFactura",$iddetalle,"Insertar",$str_insert_detalle);				}//end iif		}//end for($i = 1; $i < $Items; $i++)		//Realizar el Movimiento correspondiente en la tabla de Codificacion especifica	for($i = 1; $i <= $Items; $i++)	{				$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$existencias = get_field( "CodificacionEspecifica","Existencias","IDCodificacionEspecifica", $frm[$IDCodificacion]);				$existencias = $existencias - $frm[$Cantidad];				$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = '$existencias' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		//echo $str_actualiza_inventario .= "<br>";				db_query( $str_actualiza_inventario );				//insertar el log		insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);			}//end for($i = 1; $i < $Items; $i++)		$frm['ValorIVA'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorIVA']);		$frm['ValorTotal'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorTotal']);				$sql_actualizafactura = "UPDATE Factura SET ValorIVA = '$frm[ValorIVA]', ValorTotal = '$frm[ValorTotal]' WHERE IDFactura = '$frm[IDFactura]'";	db_query($sql_actualizafactura);		//insertar el log	insertlog($ID_Usuario,"Factura",$frm[IDFactura],"Actualizar",$sql_actualizafactura);		//Insertar Resolucion DIAN del Punto de Venta		$Resolucion = get_field("PuntoVenta","Resolucion","IDPuntoVenta",$frm['IDPuntoVenta']);	$RDesde = get_field("PuntoVenta","RDesde","IDPuntoVenta",$frm['IDPuntoVenta']);	$RHasta = get_field("PuntoVenta","RHasta","IDPuntoVenta",$frm['IDPuntoVenta']);		$sql_actualizafactura = "UPDATE Factura SET Resolucion = '$Resolucion', RDesde = '$RDesde', RHasta = '$RHasta' WHERE IDFactura = '$frm[IDFactura]'";	db_query($sql_actualizafactura);		//insertar el log	insertlog($ID_Usuario,"Factura",$frm[IDFactura],"Actualizar",$sql_actualizafactura);	}//end function venta( $frm )/*******************************************************************************************	agregarventaempleado:Agrega un regisro a la tabla de ventas empleados necesaria para el calculo de la comision.			$frm: array con los datos de salida de mercancia	Retorna:				Void*******************************************************************************************/function agregarventaempleado( $frm ){	//print_r($frm);	$administrador = get_field("PuntoVenta","IDEmpleado","IDEmpleado",$frm['IDEmpleado']);	if($administrador <> "")		$cargo = "Administrador";	else		$cargo = "Empleado";		$frm['ValorTotal'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorTotal']);		$idadministrador = get_field("PuntoVenta","IDEmpleado","IDPuntoVenta",$frm['IDPuntoVenta']);	$idventaempleado = get_maxID("VentasEmpleado","IDVentasEmpleado");	$sql_ventaadministrador = "INSERT INTO VentasEmpleado VALUES ('$idventaempleado','$idadministrador','Administrador','$frm[IDPuntoVenta]','$frm[IDFactura]','$frm[ValorTotal]')";	$queryventaadministrador = db_query($sql_ventaadministrador);			if($cargo == "Empleado")	{		$idventaempleado = get_maxID("VentasEmpleado","IDVentasEmpleado");		$sql_ventaempleado = "INSERT INTO VentasEmpleado VALUES ('$idventaempleado','$frm[IDEmpleado]','$cargo','$frm[IDPuntoVenta]','$frm[IDFactura]','$frm[ValorTotal]')";		$queryventaempleado = db_query($sql_ventaempleado);	}}/*******************************************************************************************	Libreria de funciones para el Sistema de Puntos de Venta de Caprino - Salidas de MErcancia	Creador por: John Escobar	Iniciado: Agosto 11/2005	Ultima Modificación: Agosto 11/2005*******************************************************************************************//*******************************************************************************************	venta: Realiza todos los movimiento necesarios cuando se hace una venta con bonos en el punto de venta.	Parametros:			$frm: array con los datos de venta	Retorna:				Void*******************************************************************************************/function ventabono( $frm ){	Global $Nombre_Usuario, $ID_Usuario, $Table, $Key, $MOD, $IVA;		//Insertar los Items en la tabla de detalles		$Items = $frm['ITEM'];		//print_r( $frm );		for($i = 1; $i <= $Items; $i++)	{				$iddetalle = get_maxID("DetalleFacturaBono WHERE IDFacturaBono = '$frm[IDFacturaBono]' ","IDDetalleFacturaBono");		$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$ValorU = "ValorU".$i;		$PrecioU = "Precio".$i;		$DescuentoRef = "Descuento".$i;				$ValorU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$ValorU]);		$PrecioU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$PrecioU]).".00";		$DescuentoRef = $frm[$DescuentoRef];				$str_insert_detalle  = "INSERT INTO DetalleFacturaBono ( IDDetalleFacturaBono,IDFacturaBono,IDCodificacionEspecifica,Cantidad,ValorU,PrecioU,DescuentoRef,UsuarioTrCr,FechaTrCr ) ";		echo $str_insert_detalle .= "VALUES ( '$iddetalle','$frm[IDFacturaBono]','$frm[$IDCodificacion]','$frm[$Cantidad]','$ValorU','$PrecioU','$DescuentoRef','$frm[UsuarioTrCr]','$frm[FechaTrCr]' )";				db_query( $str_insert_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleFacturaBono",$iddetalle,"Insertar",$str_insert_detalle);		}//end for($i = 1; $i < $Items; $i++)		//Realizar el Movimiento correspondiente en la tabla de Codificacion especifica	for($i = 1; $i <= $Items; $i++)	{			$IDCodificacion = "IDCodificacion".$i;	$Cantidad = "Cantidad".$i;		$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = Existencias - '$frm[$Cantidad]' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		db_query( $str_actualiza_inventario );		//insertar el log	insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);			}//end for($i = 1; $i < $Items; $i++)		$frm['ValorIVA'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorIVA']);		$frm['ValorTotal'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorTotal']);				$sql_actualizaFacturaBono = "UPDATE FacturaBono SET  ValorTotal = '$frm[ValorTotal]' WHERE IDFacturaBono = '$frm[IDFacturaBono]'";	db_query($sql_actualizaFacturaBono);		//insertar el log	insertlog($ID_Usuario,"FacturaBono",$frm[IDFacturaBono],"Actualizar",$sql_actualizaFacturaBono);		$frm['Excedente'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['Excedente']);	if( $frm['Excedente'] > 0 )	{		//INSERTAR FACTURA CON EL EXCEDENTE				$Resolucion = get_field("PuntoVenta","Resolucion","IDPuntoVenta",$frm['IDPuntoVenta']);		$RDesde = get_field("PuntoVenta","RDesde","IDPuntoVenta",$frm['IDPuntoVenta']);		$RHasta = get_field("PuntoVenta","RHasta","IDPuntoVenta",$frm['IDPuntoVenta']);				$idfactura = get_maxID( "Factura","IDFactura" );		$numerofactura = get_maxID( "Factura WHERE IDPuntoventa = '$frm[IDPuntoVenta]' ","NumeroFactura" );		$sql_insert_factura = " INSERT INTO Factura ( IDFactura, IDCliente, NumeroFactura, IDPuntoVenta, IDEmpleado, FechaFactura, ValorIVA, 								ValorTotal, Resolucion, RDesde, RHasta, UsuarioTrCr, FechaTrCr ) 								VALUES ( '$idfactura','$frm[IDCliente]','$numerofactura','$frm[IDPuntoVenta]','$frm[IDEmpleado]',NOW(),'$frm[ValorIVA]','$frm[Excedente]',								'$Resolucion','$RDesde','$RHasta','$frm[UsuarioTrCr]','$frm[FechaTrCr]' ) ";				db_query( $sql_insert_factura );				//insertar el log		insertlog($ID_Usuario,"Factura",$idfactura,"Insertar",$sql_insert_factura);				//INSERTAR DETALLE FACTURA		//se agrega el excedente como una referencia - el id de la referencia excedente esta guardada en la tabla parametros IDParametro = 1				$IDExcedente = get_field( "Parametros","Parametro","IDParametro",1 );		$IDCod = get_field( "CodificacionEspecifica","IDCodificacionEspecifica","IDPuntoVentaReferencia",get_field( "PuntoVentaReferencia","IDPuntoVentaReferencia","IDReferencia",$IDExcedente."' AND IDPuntoVenta = '$frm[IDPuntoVenta] " ) );		$ValorU = $frm['Excedente'] * ( 1 - $IVA );		$sql_detalle = " INSERT INTO DetalleFactura (IDDetalleFactura, IDFactura, IDCodificacionEspecifica, Cantidad, ValorU, PrecioU) 							VALUES ( '1','$idfactura','$IDCod','1','$ValorU','$frm[Excedente]' ) ";				db_query( $sql_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleFactura",$idfactura,"Insertar",$sql_detalle);									//ACTUALIZAR FACTURA BONO CON EL ID DE LA FACTURA		$sql_actualizafacturaBono = "UPDATE FacturaBono SET IDFactura = '$idfactura' WHERE IDFacturaBono = '$frm[IDFacturaBono]' ";		db_query( $sql_actualizafacturaBono );				//insertar el log		insertlog($ID_Usuario,"FacturaBono",$frm['IDFacturaBono'],"Insertar",$sql_actualizafacturaBono);											$frm['IDFactura'] = $idfactura;		//ACTUALIZAR VENTAS VENDEDOR		agregarventaempleadobono($frm);							}//end if $frm[Excedente]		return $frm;	}//end function venta( $frm )/*******************************************************************************************	Libreria de funciones para el Sistema de Puntos de Venta de Caprino - Salidas de MErcancia	Creador por: John Escobar	Iniciado: Agosto 11/2005	Ultima Modificación: Agosto 11/2005*******************************************************************************************//*******************************************************************************************	ventacambio: Realiza todos los movimiento necesarios cuando se hace una venta con bonos en el punto de venta.	Parametros:			$frm: array con los datos de venta	Retorna:				Void*******************************************************************************************/function ventacambio( $frm ){	Global $Nombre_Usuario, $ID_Usuario, $Table, $Key, $MOD, $IVA;		//Insertar los Items en la tabla de detalles		$Items = $frm['ITEM'];		//print_r( $frm );			for($i = 1; $i <= $Items; $i++)	{				$iddetalle = get_maxID("DetalleCambio WHERE IDCambio = '$frm[IDCambio]' ","IDCambio");		$IDCodificacion = "IDCodificacion".$i;				$IDCodificacionCambio = "IDCodificacionC1";		$Cantidad = "Cantidad".$i;		$ValorU = "ValorU".$i;		$PrecioU = "Precio".$i;		$DescuentoRef = "Descuento".$i;				$ValorU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$ValorU]);		$PrecioU = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm[$PrecioU]).".00";		$DescuentoRef = $frm[$DescuentoRef];				$str_insert_detalle  = "INSERT INTO DetalleCambio ( IDDetalleCambio,IDCambio,IDCodificacionEspecificaCambio,IDCodificacionEspecifica,Cantidad,ValorU,PrecioU,DescuentoRef,UsuarioTrCr,FechaTrCr ) ";		$str_insert_detalle .= "VALUES ( '$iddetalle','$frm[RegistroCambio]','$frm[$IDCodificacionCambio]','$frm[$IDCodificacion]','$frm[$Cantidad]','$ValorU','$PrecioU','$DescuentoRef','$frm[UsuarioTrCr]','$frm[FechaTrCr]' )";				db_query( $str_insert_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleCambio",$iddetalle,"Insertar",$str_insert_detalle);		}//end for($i = 1; $i < $Items; $i++)		//Realizar el Movimiento correspondiente en la tabla de Codificacion especifica	//Aumentar inventario	$IDCodificacion = "IDCodificacionC1";	$Cantidad = "CantidadC1";		$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = Existencias + '$frm[$Cantidad]' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		db_query( $str_actualiza_inventario );		//insertar el log	insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);			//Disminuir inventario			$IDCodificacion = "IDCodificacion1";	$Cantidad = "Cantidad1";		$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = Existencias - '$frm[$Cantidad]' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		db_query( $str_actualiza_inventario );		//insertar el log	insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);				$frm['ValorIVA'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorIVA']);		$frm['ValorTotal'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['ValorTotal']);				$sql_actualizaFacturaBono = "UPDATE Cambio SET  ValorTotal = '$frm[ValorTotal]' WHERE IDCambio = '$frm[RegistroCambio]'";	db_query($sql_actualizaFacturaBono);		//insertar el log	insertlog($ID_Usuario,"Cambio",$frm[RegistroCambio],"Actualizar",$sql_actualizaFacturaBono);		$frm['Excedente'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['Excedente']);	if( $frm['Excedente'] > 0 )	{		//INSERTAR FACTURA CON EL EXCEDENTE				$Resolucion = get_field("PuntoVenta","Resolucion","IDPuntoVenta",$frm['IDPuntoVenta']);		$RDesde = get_field("PuntoVenta","RDesde","IDPuntoVenta",$frm['IDPuntoVenta']);		$RHasta = get_field("PuntoVenta","RHasta","IDPuntoVenta",$frm['IDPuntoVenta']);				$idfactura = get_maxID( "Factura","IDFactura" );		$numerofactura = get_maxID( "Factura WHERE IDPuntoventa = '$frm[IDPuntoVenta]' ","NumeroFactura" );		$sql_insert_factura = " INSERT INTO Factura ( IDFactura, IDCliente, NumeroFactura, IDPuntoVenta, IDEmpleado, FechaFactura, ValorIVA, 								ValorTotal, Resolucion, RDesde, RHasta, UsuarioTrCr, FechaTrCr ) 								VALUES ( '$idfactura','$frm[IDCliente]','$numerofactura','$frm[IDPuntoVenta]','$frm[IDEmpleado]',NOW(),'$frm[ValorIVA]','$frm[Excedente]',								'$Resolucion','$RDesde','$RHasta','$frm[UsuarioTrCr]','$frm[FechaTrCr]' ) ";				db_query( $sql_insert_factura );				//insertar el log		insertlog($ID_Usuario,"Factura",$idfactura,"Insertar",$sql_insert_factura);				//INSERTAR DETALLE FACTURA		//se agrega el excedente como una referencia - el id de la referencia excedente esta guardada en la tabla parametros IDParametro = 1				$IDExcedente = get_field( "Parametros","Parametro","IDParametro",1 );		$IDCod = get_field( "CodificacionEspecifica","IDCodificacionEspecifica","IDPuntoVentaReferencia",get_field( "PuntoVentaReferencia","IDPuntoVentaReferencia","IDReferencia",$IDExcedente."' AND IDPuntoVenta = '$frm[IDPuntoVenta] " ) );		$ValorU = $frm['Excedente'] * ( 1 - $IVA );		$sql_detalle = " INSERT INTO DetalleFactura (IDDetalleFactura, IDFactura, IDCodificacionEspecifica, Cantidad, ValorU, PrecioU) 							VALUES ( '1','$idfactura','$IDCod','1','$ValorU','$frm[Excedente]' ) ";				db_query( $sql_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleFactura",$idfactura,"Insertar",$sql_detalle);									//ACTUALIZAR FACTURA BONO CON EL ID DE LA FACTURA		$sql_actualizafacturaBono = "UPDATE Cambio SET IDFactura = '$idfactura' WHERE IDCambio = '$frm[RegistroCambio]' ";		db_query( $sql_actualizafacturaBono );				//insertar el log		insertlog($ID_Usuario,"FacturaBono",$frm['IDFacturaBono'],"Insertar",$sql_actualizafacturaBono);											$frm['IDFactura'] = $idfactura;		//ACTUALIZAR VENTAS VENDEDOR		agregarventaempleadobono($frm);							}//end if $frm[Excedente]		return $frm;	}//end function venta( $frm )/*******************************************************************************************	agregarventaempleadobono:Agrega un regisro a la tabla de ventas empleados necesaria para el calculo de la comision.			$frm: array con los datos de salida de mercancia	Retorna:				Void*******************************************************************************************/function agregarventaempleadobono( $frm ){	//print_r($frm);	$administrador = get_field("PuntoVenta","IDEmpleado","IDEmpleado",$frm['IDEmpleado']);	if($administrador <> "")		$cargo = "Administrador";	else		$cargo = "Empleado";		$frm['Excedente'] = preg_replace("[\$\%\!\@\#\^\&\*\(\)\=\~\`\?\{\}\'\:\'\;\<\>\,]","",$frm['Excedente']);		$idadministrador = get_field("PuntoVenta","IDEmpleado","IDPuntoVenta",$frm['IDPuntoVenta']);	$idventaempleado = get_maxID("VentasEmpleado","IDVentasEmpleado");	$sql_ventaadministrador = "INSERT INTO VentasEmpleado VALUES ('$idventaempleado','$idadministrador','Administrador','$frm[IDPuntoVenta]','$frm[IDFactura]','$frm[Excedente]')";	$queryventaadministrador = db_query($sql_ventaadministrador);			if($cargo == "Empleado")	{		$idventaempleado = get_maxID("VentasEmpleado","IDVentasEmpleado");		$sql_ventaempleado = "INSERT INTO VentasEmpleado VALUES ('$idventaempleado','$frm[IDEmpleado]','$cargo','$frm[IDPuntoVenta]','$frm[IDFactura]','$frm[Excedente]')";		$queryventaempleado = db_query($sql_ventaempleado);	}}/*******************************************************************************************	salidamercancia:Realiza la salida de mercancia de un punto de venta por otros conceptos 	que no son la venta.			$frm: array con los datos de salida de mercancia	Retorna:				Void*******************************************************************************************/function salidamercancia( $frm ){	Global $Nombre_Usuario, $ID_Usuario;		//Insertar los Items en la tabla de detalles		$Items = $frm['ITEM'];		for($i = 1; $i <= $Items; $i++)	{				$iddetalle = get_maxID("DetalleMovimiento","IDDetalleMovimiento");		$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$IDPuntoVentaReferencia = get_field( "CodificacionEspecifica","IDPuntoVentaReferencia","IDCodificacionEspecifica", $frm[$IDCodificacion]);		$IDTalla = get_field( "CodificacionEspecifica","IDTalla","IDCodificacionEspecifica", $frm[$IDCodificacion]);				$str_insert_detalle  = "INSERT INTO DetalleMovimiento ( IDDetalleMovimiento,IDMovimiento,IDPuntoVentaReferencia,IDTalla,Cantidad,UsuarioTrCr,FechaTrCr ) ";		$str_insert_detalle .= "VALUES ( '$iddetalle','$frm[IDMovimiento]','$IDPuntoVentaReferencia','$IDTalla','$frm[$Cantidad]','$frm[UsuarioTrCr]','$frm[FechaTrCr]' )";		//echo $str_insert_detalle .= "<br>";				db_query( $str_insert_detalle );				//insertar el log		insertlog($ID_Usuario,"DetalleMovimiento",$iddetalle,"Insertar",$str_insert_detalle);		}//end for($i = 1; $i < $Items; $i++)		//Realizar el Movimiento correspondiente en la tabla de Codificacion especifica	for($i = 1; $i <= $Items; $i++)	{				$IDCodificacion = "IDCodificacion".$i;		$Cantidad = "Cantidad".$i;		$existencias = get_field( "CodificacionEspecifica","Existencias","IDCodificacionEspecifica", $frm[$IDCodificacion]);				$existencias = $existencias - $frm[$Cantidad];				$str_actualiza_inventario  = "UPDATE CodificacionEspecifica SET Existencias = '$existencias' WHERE IDCodificacionEspecifica = '$frm[$IDCodificacion]'";		//echo $str_actualiza_inventario .= "<br>";				db_query( $str_actualiza_inventario );				//insertar el log		insertlog($ID_Usuario,"CodificacionEspecifica",$frm[$IDCodificacion],"Insertar",$str_actualiza_inventario);			}//end for($i = 1; $i < $Items; $i++)	}//end function salidamercancia( $frm )?>